# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"
require "webmock/rspec"

RSpec.describe "Timekeeping relay test hooks", type: :request do
  it "a relay paused through the hook route sends nothing until the resume route is called" do
    token = "test-hooks-spec-service-token"
    stamp = Time.utc(2026, 3, 2, 9)
    OutboxSnapshot.create!(
      "outbox_position" => 41, "id" => 4100, "project_id" => 3, "user_id" => 4, "agent_id" => nil,
      "work_date" => Date.new(2026, 3, 2), "duration" => 60.0, "note" => nil, "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => stamp, "updated_at" => stamp, "company_id" => 1, "version" => 1,
      "generation" => 1
    )
    delivery = stub_request(:post, %r{\Ahttp://monolith\.test-hooks\.test})
      .to_return(status: 200, body: { applied: 1, ignored: 0 }.to_json, headers: { "Content-Type" => "application/json" })

    with_timekeeping_env(
      Timekeeping::Environment::MONOLITH_SNAPSHOT_URL => "http://monolith.test-hooks.test",
      Timekeeping::Environment::SERVICE_TOKEN => token
    ) do
      post "/internal/v1/test-hooks/relay/pause", headers: { "Authorization" => "Bearer #{token}" }
      expect(response).to have_http_status(:success)
      begin
        # "A paused relay sends nothing until resumed"
        RelayJob.perform_now
        expect(delivery).not_to have_been_requested
        expect(OutboxSnapshot.find(41).sent_at).to be_nil
      ensure
        post "/internal/v1/test-hooks/relay/resume", headers: { "Authorization" => "Bearer #{token}" }
      end
      expect(response).to have_http_status(:success)

      RelayJob.perform_now
    end

    expect(delivery).to have_been_requested.once
    expect(OutboxSnapshot.find(41).sent_at).not_to be_nil
  end
end


RSpec.describe "Timekeeping relay test hooks", type: :request do
  it "the pause and resume hook routes refuse a caller without the service token" do
    with_timekeeping_env(Timekeeping::Environment::SERVICE_TOKEN => "test-hooks-refusal-service-token") do
      post "/internal/v1/test-hooks/relay/pause", headers: { "Authorization" => "Bearer not-the-service-token" }
      expect(response).to have_http_status(:unauthorized)

      post "/internal/v1/test-hooks/relay/resume"
      expect(response).to have_http_status(:unauthorized)
    end
  end
end
